// UMAMI wrapper for the custom %(kind)s function, generated by bin/init_custom_func.
// It unpacks the batched UMAMI inputs and calls %(function_name)s once per event,
// one GPU thread per event. Write your function in %(body_file)s and its parameters
// in parameters.h, there is no need to edit this file.

#include "umami.h"

#include <cstddef>
#include <cstdio>
#include <cstring>

#ifdef __HIPCC__
#include <hip/hip_runtime.h>
typedef hipStream_t gpuStream_t;
#define gpuGetLastError hipGetLastError
#define gpuSuccess hipSuccess
#define UMAMI_GPU_DEVICE UMAMI_DEVICE_HIP
#else
#include <cuda_runtime.h>
typedef cudaStream_t gpuStream_t;
#define gpuGetLastError cudaGetLastError
#define gpuSuccess cudaSuccess
#define UMAMI_GPU_DEVICE UMAMI_DEVICE_CUDA
#endif

#define CUSTOM_IS_PDF %(is_pdf)d
#define CUSTOM_IS_SCALE %(is_scale)d

// the function body is compiled into this translation unit
#include "%(body_file)s"

namespace {

constexpr int thread_count = 256;
constexpr UmamiOutputKey output_keys[] = {%(output_keys)s};
constexpr std::size_t output_key_count = sizeof(output_keys) / sizeof(output_keys[0]);

#define CUSTOM_DEFAULT(name, value) value,
const CustomParameters default_parameters = {CUSTOM_PARAMETERS(CUSTOM_DEFAULT) 0.};
#undef CUSTOM_DEFAULT

struct ParameterEntry {
    const char* name;
    std::size_t offset;
};
#define CUSTOM_ENTRY(name, value) {#name, offsetof(CustomParameters, name)},
const ParameterEntry parameter_entries[] = {CUSTOM_PARAMETERS(CUSTOM_ENTRY){nullptr, 0}};
#undef CUSTOM_ENTRY

#if CUSTOM_IS_PDF
constexpr UmamiInputKey input_keys[] = {
    UMAMI_IN_MOMENTUM_FRACTION, UMAMI_IN_SCALE, UMAMI_IN_PDG_ID, UMAMI_IN_BEAM_INDEX
};

__global__ void evaluate(
    std::size_t count,
    const double* x,
    const double* q,
    const int* pdg_id,
    const int* beam_index,
    CustomParameters params,
    double* output
) {
    std::size_t i = blockDim.x * blockIdx.x + threadIdx.x;
    if (i < count) {
        output[i] = %(function_name)s(beam_index[i], pdg_id[i], x[i], q[i], &params);
    }
}
#else
constexpr UmamiInputKey input_keys[] = {
    UMAMI_IN_MOMENTA, UMAMI_IN_PARTICLE_COUNT, UMAMI_IN_PDG_IDS
};
// largest particle count supported by the GPU wrapper, raise it with
// make CFLAGS=-DCUSTOM_MAX_PARTICLE_COUNT=64
#ifndef CUSTOM_MAX_PARTICLE_COUNT
#define CUSTOM_MAX_PARTICLE_COUNT 32
#endif
constexpr int max_particle_count = CUSTOM_MAX_PARTICLE_COUNT;

struct OutputPointers {
    double* values[3];
};

__global__ void evaluate(
    std::size_t count,
    std::size_t stride,
    const double* momenta,
    const int* particle_count,
    const int* pdg_ids,
    CustomParameters params,
    OutputPointers output
) {
    std::size_t i = blockDim.x * blockIdx.x + threadIdx.x;
    if (i >= count) {
        return;
    }
    int n = particle_count[i];
    if (n > max_particle_count) {
        // abort the kernel, the error then surfaces at the next GPU call
        printf(
            "custom %(kind)s: %%d particles, the wrapper supports at most %%d. Rebuild "
            "with make CFLAGS=-DCUSTOM_MAX_PARTICLE_COUNT=<n>\n",
            n,
            max_particle_count
        );
#ifdef __HIPCC__
        abort();
#else
        __trap();
#endif
    }
    int event_pdg_ids[max_particle_count];
    double event_momenta[max_particle_count][4];
    // column-major layout with the batch dimension contiguous
    for (int j = 0; j < n; ++j) {
        event_pdg_ids[j] = pdg_ids[stride * j + i];
        for (int k = 0; k < 4; ++k) {
            event_momenta[j][k] = momenta[stride * (n * k + j) + i];
        }
    }
#if CUSTOM_IS_SCALE
    double scales[3];
    %(function_name)s(
        n, event_pdg_ids, event_momenta, &params, &scales[0], &scales[1], &scales[2]
    );
    for (int j = 0; j < 3; ++j) {
        if (output.values[j] != nullptr) {
            output.values[j][i] = scales[j];
        }
    }
#else
    // a cut returns bool, converted to 1 or 0
    output.values[0][i] =
        static_cast<double>(%(function_name)s(n, event_pdg_ids, event_momenta, &params));
#endif
}
#endif

struct KeyTables {
    bool inputs[UMAMI_INPUT_KEY_COUNT] = {};
    bool outputs[UMAMI_OUTPUT_KEY_COUNT] = {};
    KeyTables() {
        for (auto key : input_keys) {
            inputs[key] = true;
        }
        for (auto key : output_keys) {
            outputs[key] = true;
        }
        outputs[UMAMI_OUT_GPU_STREAM] = true;
    }
};
const KeyTables key_tables;

double* find_parameter(UmamiHandle handle, char const* name) {
    for (auto entry = parameter_entries; entry->name != nullptr; ++entry) {
        if (std::strcmp(entry->name, name) == 0) {
            return reinterpret_cast<double*>(static_cast<char*>(handle) + entry->offset);
        }
    }
    return nullptr;
}

} // namespace

extern "C" {

UmamiStatus umami_get_meta(UmamiMetaKey meta_key, void* result) {
    if (meta_key == UMAMI_META_DEVICE) {
        *static_cast<UmamiDevice*>(result) = UMAMI_GPU_DEVICE;
        return UMAMI_SUCCESS;
    }
    return UMAMI_ERROR_UNSUPPORTED_META;
}

UmamiStatus umami_supported_inputs(bool const** supported, int* count) {
    *supported = key_tables.inputs;
    *count = UMAMI_INPUT_KEY_COUNT;
    return UMAMI_SUCCESS;
}

UmamiStatus umami_required_inputs(bool const** required, int* count) {
    return umami_supported_inputs(required, count);
}

UmamiStatus umami_supported_outputs(bool const** supported, int* count) {
    *supported = key_tables.outputs;
    *count = UMAMI_OUTPUT_KEY_COUNT;
    return UMAMI_SUCCESS;
}

UmamiStatus umami_initialize(UmamiHandle* handle, char const*) {
    // each instance holds its own parameter values, passed to the kernel by value
    *handle = new CustomParameters(default_parameters);
    return UMAMI_SUCCESS;
}

UmamiStatus umami_set_parameter(UmamiHandle handle, char const* name, double real, double) {
    double* parameter = find_parameter(handle, name);
    if (parameter == nullptr) {
        return UMAMI_ERROR;
    }
    *parameter = real;
    return UMAMI_SUCCESS;
}

UmamiStatus umami_get_parameter(UmamiHandle handle, char const* name, double* real, double* imag) {
    double* parameter = find_parameter(handle, name);
    if (parameter == nullptr) {
        return UMAMI_ERROR;
    }
    *real = *parameter;
    *imag = 0.;
    return UMAMI_SUCCESS;
}

UmamiStatus umami_matrix_element(
    UmamiHandle handle,
    std::size_t count,
    std::size_t stride,
    std::size_t offset,
    std::size_t input_count,
    UmamiInputKey const* input_keys_in,
    void const* const* inputs,
    std::size_t output_count,
    UmamiOutputKey const* output_keys_in,
    void* const* outputs
) {
    const CustomParameters& params = *static_cast<const CustomParameters*>(handle);
    // output pointers in the order of output_keys, nullptr if not requested
    double* output[3] = {nullptr, nullptr, nullptr};
    bool any_output = false;
    gpuStream_t stream = nullptr;
    for (std::size_t i = 0; i < output_count; ++i) {
        if (output_keys_in[i] == UMAMI_OUT_GPU_STREAM) {
            stream = static_cast<gpuStream_t>(outputs[i]);
            continue;
        }
        bool known = false;
        for (std::size_t j = 0; j < output_key_count; ++j) {
            if (output_keys_in[i] == output_keys[j]) {
                output[j] = static_cast<double*>(outputs[i]) + offset;
                known = any_output = true;
            }
        }
        if (!known) {
            return UMAMI_ERROR_UNSUPPORTED_OUTPUT;
        }
    }
    if (!any_output || count == 0) {
        return UMAMI_SUCCESS;
    }
    unsigned int block_count = (count + thread_count - 1) / thread_count;

#if CUSTOM_IS_PDF
    const double* x = nullptr;
    const double* q = nullptr;
    const int* pdg_id = nullptr;
    const int* beam_index = nullptr;
    for (std::size_t i = 0; i < input_count; ++i) {
        switch (input_keys_in[i]) {
        case UMAMI_IN_MOMENTUM_FRACTION:
            x = static_cast<const double*>(inputs[i]) + offset;
            break;
        case UMAMI_IN_SCALE:
            q = static_cast<const double*>(inputs[i]) + offset;
            break;
        case UMAMI_IN_PDG_ID:
            pdg_id = static_cast<const int*>(inputs[i]) + offset;
            break;
        case UMAMI_IN_BEAM_INDEX:
            beam_index = static_cast<const int*>(inputs[i]) + offset;
            break;
        default:
            return UMAMI_ERROR_UNSUPPORTED_INPUT;
        }
    }
    if (!x || !q || !pdg_id || !beam_index) {
        return UMAMI_ERROR_MISSING_INPUT;
    }
    evaluate<<<block_count, thread_count, 0, stream>>>(
        count, x, q, pdg_id, beam_index, params, output[0]
    );
#else
    const double* momenta = nullptr;
    const int* particle_count = nullptr;
    const int* pdg_ids = nullptr;
    for (std::size_t i = 0; i < input_count; ++i) {
        switch (input_keys_in[i]) {
        case UMAMI_IN_MOMENTA:
            momenta = static_cast<const double*>(inputs[i]) + offset;
            break;
        case UMAMI_IN_PARTICLE_COUNT:
            particle_count = static_cast<const int*>(inputs[i]) + offset;
            break;
        case UMAMI_IN_PDG_IDS:
            pdg_ids = static_cast<const int*>(inputs[i]) + offset;
            break;
        default:
            return UMAMI_ERROR_UNSUPPORTED_INPUT;
        }
    }
    if (!momenta || !particle_count || !pdg_ids) {
        return UMAMI_ERROR_MISSING_INPUT;
    }
    evaluate<<<block_count, thread_count, 0, stream>>>(
        count,
        stride,
        momenta,
        particle_count,
        pdg_ids,
        params,
        OutputPointers{{output[0], output[1], output[2]}}
    );
#endif
    return gpuGetLastError() == gpuSuccess ? UMAMI_SUCCESS : UMAMI_ERROR;
}

UmamiStatus umami_free(UmamiHandle handle) {
    delete static_cast<CustomParameters*>(handle);
    return UMAMI_SUCCESS;
}

} // extern "C"
